verses.tafsir:
[ <span class="arabic uthmani">فَاصْبِرْ لِحُكْمِ رَبِّكَ</span> ] ئه‌ی محمد - <span class="saw">صلی الله علیه وسلم</span> -  تۆ ئارام بگره‌ بۆ حوكم و بڕیاری په‌روه‌ردگارت له‌سه‌ر ئازاردانى نه‌ته‌وه‌كه‌ت
{یونس پێغه‌مبه‌ر - <span class="saw">صلی الله علیه وسلم</span> -}
 [ <span class="arabic uthmani">وَلَا تَكُنْ كَصَاحِبِ الْحُوتِ إِذْ نَادَى</span> ] وه‌ تۆ وه‌كو یونسى هاوه‌ڵی نه‌هه‌نگه‌كه‌ - <span class="saw">صلی الله علیه وسلم</span> -  مه‌به‌ كه‌ له‌ قه‌ومه‌كه‌ی تووڕه‌بوو به‌جێی هێشتن وه‌ دواتر له‌ناو ده‌ریاكه‌ نه‌هه‌نگه‌كه‌ قوتیداو دواتر له‌ناو سكى نه‌هه‌نگه‌كه‌ داوای لێخۆشبوونی له‌ خوای گه‌وره‌ كردو خوای گه‌وره‌ فه‌رمانی به‌ نه‌هه‌نگه‌كه‌ كرد فڕێی دایه‌ ده‌ره‌وه‌ [ <span class="arabic uthmani">وَهُوَ مَكْظُومٌ (٤٨)</span> ] كه‌ ئه‌م دواتر غه‌م و په‌ژاره‌و خه‌فه‌تی خوارد، یاخود له‌ناو سكی نه‌هه‌نگه‌كه‌دا به‌ند كرا.

خوای گه‌وره‌یش فه‌رمووی: 
{حیكمه‌ت له‌وه‌ى ده‌رگاوانانى دۆزه‌خ مه‌لائیكه‌تن}
[ <span class="arabic uthmani">وَمَا جَعَلْنَا أَصْحَابَ النَّارِ إِلَّا مَلَائِكَةً</span> ] ئێمه‌ ته‌نها مه‌لائیكه‌تمان داناوه‌ به‌ ده‌رگاوانى دۆزه‌خ چونكه‌ ئێوه‌ توانای مه‌لائیكه‌تتان نیه‌، كێ هه‌یه‌ به‌سه‌ر مه‌لائیكه‌تدا زاڵ بێ [ <span class="arabic uthmani">وَمَا جَعَلْنَا عِدَّتَهُمْ إِلَّا فِتْنَةً لِلَّذِينَ كَفَرُوا</span> ] وه‌ ئه‌م ژماره‌یه‌ش كه‌ ئه‌ڵێین: نۆزده‌یه‌ ئه‌مه‌ بۆ تاقیكردنه‌وه‌ی كافرانه‌ [ <span class="arabic uthmani">لِيَسْتَيْقِنَ الَّذِينَ أُوتُوا الْكِتَابَ</span> ] تا ئه‌هلی كتابیش بگه‌ن به‌ یه‌قین له‌به‌ر ئه‌وه‌ی له‌ كتێبه‌كانی ئه‌وانیشدا هاتووه‌ كه‌ ژماره‌ی ده‌رگاوانانی دۆزه‌خ نۆزده‌یه‌ [ <span class="arabic uthmani">وَيَزْدَادَ الَّذِينَ آمَنُوا إِيمَانًا</span> ] وه‌ تا باوه‌ڕدارانیش ئیمانیان زیاتر بكات كه‌ ئه‌بینن ئه‌و ژماره‌یه‌ له‌ كتێبه‌كانی ئه‌هلی كتابیش هاتووه‌ [ <span class="arabic uthmani">وَلَا يَرْتَابَ الَّذِينَ أُوتُوا الْكِتَابَ وَالْمُؤْمِنُونَ</span> ] وه‌ تا ئه‌هلی كتاب و باوه‌ڕدارانیش تووشی گومان نه‌بن [ <span class="arabic uthmani">وَلِيَقُولَ الَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ وَالْكَافِرُونَ مَاذَا أَرَادَ اللَّهُ بِهَذَا مَثَلًا</span> ] وه‌ تا ئه‌وانه‌ی نه‌خۆشی گومان له‌ دڵیاندا هه‌یه‌، واته‌: مونافیقان، وه‌ كافرانیش بڵێن: باشه‌ خوای گه‌وره‌ مه‌به‌ستی چیه‌ له‌م نموونه‌ هێنانه‌وه‌یه‌؟ وه‌ حیكمه‌ت چیه‌ له‌م ژماره‌ سه‌یرو سه‌مه‌ره‌یه‌ [ <span class="arabic uthmani">كَذَلِكَ يُضِلُّ اللَّهُ مَنْ يَشَاءُ وَيَهْدِي مَنْ يَشَاءُ</span> ] به‌م شێوازه‌ خوای گه‌وره‌ هه‌ر كه‌سێك گومڕا ئه‌كات كه‌ ویستی لێ بێت و شایه‌نی هیدایه‌ت نه‌بێت و ڕێگای هیدایه‌ت نه‌گرێته‌به‌ر، وه‌ هیدایه‌تی هه‌ر كه‌سێك ئه‌دات كه‌ ویستی لێ بێت و شایه‌نی هیدایه‌ت بێت و ڕێگای هیدایه‌ت بگرێته‌ به‌ر [ <span class="arabic uthmani">وَمَا يَعْلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَ</span> ] وه‌ ژماره‌ی سه‌ربازانی خوای گه‌وره‌ خۆی نه‌بێ كه‌س نازانێ چه‌نده‌، له‌ ئاسمانی حه‌وته‌مدا له‌ (بیت المعمور) دا هه‌موو ڕۆژێك حه‌فتا هه‌زار مه‌لائیكه‌ت ئه‌چنه‌ ناوی و عیباده‌تی خوای گه‌وره‌ ئه‌كه‌ن و نایه‌نه‌ ده‌ره‌وه‌، بۆ ڕۆژی دووه‌م حه‌فتا هه‌زاری تر، به‌رده‌وام ڕۆژانه‌ حه‌فتا هه‌زار مه‌لائیكه‌ت ئه‌چێته‌ ناو (بیت المعمور)ه‌وه‌، وه‌كو پێغه‌مبه‌رى خوا - <span class="saw">صلی الله علیه وسلم</span> -  له‌ فه‌رمووده‌ی بوخاری و موسلیمدا ئه‌فه‌رمووێ، وه‌ له‌ فه‌رمووده‌ی تردا ئه‌فه‌رمووێ: ئه‌و ئاسمانه‌ فراوانه‌ شوێنی په‌نجه‌یه‌كی تیا نه‌ماوه‌ ئیلا مه‌لائیكه‌ت له‌ سوجده‌دان و سوجده‌ بۆ خوای گه‌وره‌ ئه‌به‌ن، كه‌واته‌ ژماره‌ی جنودو سه‌ربازی خوای گه‌وره‌ مه‌گه‌ر خوا خۆی بزانێ كه‌سی تر نازانێ ژماره‌یان چه‌نده‌ ئه‌وه‌نده‌ زۆرن [ <span class="arabic uthmani">وَمَا هِيَ إِلَّا ذِكْرَى لِلْبَشَرِ (٣١)</span> ] وه‌ ئه‌م ئاگرى دۆزه‌خه‌ ته‌نها یادخستنه‌وه‌یه‌ بۆ خه‌ڵكی بۆ ئه‌وه‌ی په‌ندو ئامۆژگارى وه‌ربگرن، وه‌ بزانن تواناو ده‌سه‌ڵاتی خوای گه‌وره‌ چه‌ند گه‌وره‌یه‌.

[ <span class="arabic uthmani">فَوَقَاهُمُ اللَّهُ شَرَّ ذَلِكَ الْيَوْمِ</span> ] خوای گه‌وره‌ش له‌به‌ر ئیمان و چاكه‌ كردنه‌كه‌یان له‌ شه‌ڕو سزای ئه‌و ڕۆژه‌ پاراستیانی
{هه‌ندێك له‌ نازو نیعمه‌ته‌كانى به‌هه‌شت}
 [ <span class="arabic uthmani">وَلَقَّاهُمْ نَضْرَةً وَسُرُورًا (١١)</span> ] وه‌ دڵی خۆش كردوون و ڕووی جوان كردوون له‌به‌ر ئه‌وه‌ی كه‌ دڵ خۆشبوو ڕوویش گه‌شاوه‌و جوان ئه‌بێت و پێوه‌ی دیاره‌، وه‌كو پێغه‌مبه‌ری خوا - <span class="saw">صلی الله علیه وسلم</span> -  كه‌ دڵی خۆش بوایه‌ ڕووی پیرۆزی ئه‌دره‌وشایه‌وه‌ وه‌كو پارچه‌یه‌ك له‌ مانگ ده‌رئه‌كه‌وت.
